export interface V1betaFeatureConfig {
  /** CommonFleetDefaultMemberConfigSpec contains default configuration information for memberships of a fleet */
  fleetDefaultMemberConfig?: V1betaFeature_FleetDefaultMemberConfig | Computed<V1betaFeature_FleetDefaultMemberConfig>;
  /** Labels for this Feature. */
  labels?: Record<string, string> | Computed<Record<string, string>>;
  /** Optional. Membership-specific configuration for this Feature. If this Feature does not support any per-Membership configuration, this field may be unused. The keys indicate which Membership the configuration is for, in the form: `projects/{p}/locations/{l}/memberships/{m}` Where {p} is the project, {l} is a valid location and {m} is a valid Membership in this project at that location. {p} WILL match the Feature's project. {p} will always be returned as the project number, but the project ID is also accepted during input. If the same Membership is specified in the map twice (using the project ID form, and the project number form), exactly ONE of the entries will be saved, with no guarantees as to which. For this reason, it is recommended the same format be used for all entries when mutating a Feature. */
  membershipSpecs?: Record<string, V1betaFeature_MembershipSpecs> | Computed<Record<string, V1betaFeature_MembershipSpecs>>;
  /** FeatureResourceState describes the state of a Feature *resource* in the GkeHub API. See `FeatureState` for the "running state" of the Feature in the Fleet and across Memberships. */
  resourceState?: V1betaFeature_ResourceState | Computed<V1betaFeature_ResourceState>;
  /** Optional. Scope-specific configuration for this Feature. If this Feature does not support any per-Scope configuration, this field may be unused. The keys indicate which Scope the configuration is for, in the form: `projects/{p}/locations/global/scopes/{s}` Where {p} is the project, {s} is a valid Scope in this project. {p} WILL match the Feature's project. {p} will always be returned as the project number, but the project ID is also accepted during input. If the same Scope is specified in the map twice (using the project ID form, and the project number form), exactly ONE of the entries will be saved, with no guarantees as to which. For this reason, it is recommended the same format be used for all entries when mutating a Feature. */
  scopeSpecs?: Record<string, unknown> | Computed<Record<string, unknown>>;
  /** CommonFeatureSpec contains Fleet-wide configuration information */
  spec?: V1betaFeature_Spec | Computed<V1betaFeature_Spec>;
  /** CommonFeatureState contains Fleet-wide Feature status information. */
  state?: V1betaFeature_State | Computed<V1betaFeature_State>;
}

